  // V156: each town's catacombs in their own words — what is buried there, the general's tomb, the vision, the tool he or she
  //  gives, the way back up; and how the town's own way down looks from the churchyard
  const CFG={
    0:{ entrance:'mausoleum', wayIn:'in the churchyard a mausoleum stands open, its stair going down into the catacombs.', motif:'lamb',
      intro:['Cool air, and the smell of old stone and candle-wax. The shepherds of Hearthvale are buried here, shelf above shelf.','The chapel overhead is bound by the dark. The way to it is through the tombs below.','Doors here stay open once opened, and halls stay cleared. Look for small keys, and the map.'],
      warden:{name:'The Warden of the Tombs',tip:'👹 The Warden of the Tombs — a brute: its fists come down after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'staff',relic:'crook',emoji:'🪝',name:'Shepherd’s Staff',take:'🙏 Take the crook',zone:''},
      greatKey:['Heavy, gold, and warm to the touch. A crook and a cross are cut into its bow.','It opens the great door beyond the chasm on the first level — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The brothers have laid flowers in it anyway, and left the lid where it lies.','“He is not here: for he is risen.” — Matthew 28:6 · The General walks the wall of Hearthvale again.'],
        again:['Go up, knight. The crook will carry you over the chasms the brothers cut.','The great key is in the crypts above — the ossuary set in the wall will give it up to the crook. Then the great door on the first level, the brothers’ fire, and the nave — where my body hangs.','Break the chains. And trust the One who raises the dead.'],
        open:['The tomb lies open, the lid dragged aside — and it is empty. Only his crook lies in the dust where he was laid.','You kneel. And the dome fills with a light that does not come from the oculus.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the shadow took Hearthvale. Within the month it took my body from this tomb and carried it up into the nave, and hung it there in chains, to mock the One I served. But the dead are not lost to God. He lets you see me now, as He sees me.','I knew every word of His book by heart, and never once trusted the One who spoke it. That is how the shadow took me.','Before you go up to break those chains, let me see you stand. A shepherd must turn the wolf aside before he can strike it. In this light my blows cannot kill you — but they will teach you.','Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You can turn a blow.','But a sword was never what the wolf wanted from me. It asked a question, the same one it asked in the garden — yea, hath God said? — and I reached for the page and found I had only ever had the memory of it.','So I will ask you what I could not answer.'],
        give:['Then take my crook — the shadow would not touch it. It kept my sheep; let it keep you.','{tool} — and Ⓐ Hook with it: catch the iron rings across a chasm and it swings you over; pull a lever out of reach; draw a stone ossuary out of its slot toward you.','The way on is east, across the chasm, and up. The great key lies in the crypts above. Then the great door on the first level, the brothers’ fire — and the nave, where my body hangs in its chains.','“Thy rod and thy staff they comfort me.” — Psalm 23:4'],
        toast:'🪝 The Shepherd’s Staff is yours — and his teaching is in your journal.',
        journal:'Down in the catacombs under Hearthvale\'s chapel I found {general}\'s tomb empty — the shadow has his body chained in the nave. The Lord gave me a vision of him: he sparred with me and asked me what Scripture is. {head}: {doc} He gave me his crook — the Shepherd\'s Staff.',
        codex:['2 Timothy 3:16','All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness.'] },
      folk:{name:'Brother Hollis',first:'We came back down the day the chapel was cleansed. Four hundred years of lamps — we will not let them go out again.',rest:'Every name on every shelf, read aloud once a year. It takes the whole of Lent.'},
      raiseWhy:null,
      goal:(c,inC,td)=>!c.seen?`${td.name}’s chapel is barred — go down through the mausoleum in its churchyard.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep in the catacombs.`:`Back down into ${td.name}’s catacombs — ${td.general}’s tomb lies deepest.`)
        :!c.bosskey&&!(c.doors&&c.doors['0:3,16'])?'Climb with the crook: the great key lies in the crypts above the tomb.':!(c.doors&&c.doors['0:3,16'])?'The great door on the first level — across the chasm.':`Up the stair to the nave — ${td.boss} waits.` },
    1:{ entrance:'adit', wayIn:'in the churchyard the old mine adit stands open, its rails running down into the workings under the forge.', motif:'hammer',
      intro:['Warm, still air, and the smell of iron and old coal-smoke. The smiths of Ironhold are buried here, in the galleries their fathers dug.','The chapel overhead is bound by the dark. The way to it is down, through the old workings.','Furnaces gone cold, anvils left where they stood. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Iron Warden',tip:'👹 The Iron Warden — a brute in slag and iron: its blows come down after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'hammer',relic:'hammer',emoji:'🔨',name:'Smith’s Hammer',take:'🙏 Take the hammer',zone:' · 🔨'},
      greatKey:['Heavy, gold, and warm to the touch. A hammer and a cross are cut into its bow.','It opens the great door at the head of the forge hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The smiths have laid a new-forged nail in it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General keeps the gate of Ironhold again — and lets others help her hold it.'],
        again:['Go up, knight. Break the cracked stone with the hammer — the miner the shadow caged is behind the wall in the workings above.','Free him. Then the two winches in the forge hall, the great key, the great door — and the nave, where my body hangs.','You cannot raise that gate alone. Neither could I. That was the whole of my trouble.'],
        open:['The tomb lies open, the lid shoved aside — and it is empty. Only a smith’s hammer lies in the dust where she was laid.','You kneel. And the dome fills with a light that does not come from the forges.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the shadow took Ironhold. Within the month it dragged me out of this tomb and up into the nave, and hung me there in chains — the woman who never needed anyone, hung up for the town to see. But the dead are not lost to God. He lets you see me now, as He sees me.','I forged my own armour. I would take no gift I had not earned. I prayed the way a soldier reports: my position, my strength, nothing asked. And when the Wraith came it did not break my guard. It only waited for the end of a strength that had never come from anywhere but me.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You turned it — and you did not try to take the blow on your own arm alone. You let the shield do what a shield is for.','My strength was never the question. The question is where strength comes from. So I will ask you what I could not answer.'],
        give:['Then take my hammer — and my armour, as a gift this time, not a wage. I forged them both, and thought I had made myself strong. Let the hammer break what you cannot move — and do not mistake it for the strength.','{tool} — Ⓐ Smash with it: cracked stone and the locks the shadow forged give way to it.','Above you, in the workings, the shadow caged a man behind a fall of stone — he came down to keep the forge-lamp lit and never went home. Break the wall. Free him.','The portcullis in the forge hall has two winches, too far apart for one pair of hands. You will need him. “Bear ye one another’s burdens.” — Galatians 6:2'],
        toast:'🔨 The Smith’s Hammer is yours — and her teaching is in your journal.',
        journal:'Deep in the old workings under Ironhold\'s chapel I found {general}\'s tomb empty — her body hangs in the nave. The Lord gave me a vision of her: she sparred with me and asked me who God is. {head}: {doc} She gave me her hammer — the Smith\'s Hammer — and told me I would not raise the gate alone.',
        codex:['Exodus 3:14','And God said unto Moses, I AM THAT I AM.'] },
      folk:{name:'Brother Tubal',first:'We lit the forge-lamps again the day the chapel was cleansed. Fifteen years cold. I had forgotten the sound of a bellows.',rest:'She comes down sometimes, the General, and works the bellows for us. She asks for help with the heavy pieces now. You would not believe what that costs her — or how glad she is to pay it.'},
      raiseWhy:['I was dead, knight. Truly dead. I trusted no strength but my own — and when mine ran out, there was nothing under me, and the shadow hung me here to show the town what self-made strength is worth.','And He has called me out of it, as He called Lazarus out of the tomb — and I could do nothing to help Him do it. Nothing at all. I am born again, and this time I know where strength comes from.'],
      goal:(c,inC,td)=>!c.seen?`${td.name}’s chapel is barred — go down through the old mine adit in its churchyard.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep in the old workings.`:`Back down into ${td.name}’s workings — ${td.general}’s tomb lies deepest.`)
        :!c.helper?'Break the cracked wall in the workings with the hammer, and free the caged miner.':!(c.gates&&c.gates['0:3'])?'The two winches in the forge hall — turn them together with Brother Tubal.':!(c.doors&&c.doors['0:9,9'])?'The great key, then the great door at the head of the forge hall.':`Up the stair to the nave — ${td.boss} waits.` },
    2:{ entrance:'seacave', wayIn:'below the churchyard wall a sea-stair goes down into the caves under the quay.', motif:'net',
      intro:['Salt air, cold and wet, and the slap of water somewhere below. The fisherfolk of Saltmere are buried here, in the caves the sea cut under the town.','The chapel overhead is bound by the dark. The way to it is down, through the sea-caves.','Doors stay open once opened; halls stay cleared. Look for keys, and the map — and mind the tide.'],
      warden:{name:'The Drowned Warden',tip:'👹 The Drowned Warden — a brute, slow and heavy with sea-water: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'bell',relic:'bell',emoji:'🔔',name:'Tide Bell',take:'🙏 Take the bell',zone:' · 🔔'},
      greatKey:['Heavy, gold, and warm to the touch. A bell and a cross are cut into its bow.','It opens the great door at the head of the net-menders’ hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The fisherfolk have hung a net over it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General walks the quay of Saltmere again — and knows every name on it.'],
        again:['Go up, knight. Ring the bell from the ledges in the flooded galleries and the tide will go out for you.','On the floor of the galleries, and behind the stone they mortared over, are the people I stopped counting. Read their names. All of them.','Then the ledger-vault will open, and the great key, and the great door — and the nave, where my body hangs.'],
        open:['The tomb lies open, the lid dragged aside — and it is empty. Only a small bronze bell lies in the wet where he was laid.','You kneel. And the dome fills with a light that does not come off the water.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the shadow came in on the tide and took Saltmere. Within the month it took me out of this tomb and hung me in the nave in chains, with my ledger at my feet. But the dead are not lost to God. He lets you see me now, as He sees me.','I kept Saltmere’s accounts for twenty years. Souls became hands, hands became numbers, numbers became acceptable losses. The Specter took the ones I had stopped counting first — and I did not notice they were gone until the column would not balance.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You watched me, not my sword. You looked at the one in front of you.','That was the thing I lost. So I will ask you what I could not answer — what a person is.'],
        give:['Then take my bell — and my gauntlets. I rang the bell to call the tide in, to float the boats, to get the catch counted. Ring it now to let the water go out, and go down to where they are.','{tool} — Ⓐ Ring it at the bell-posts on the ledges, and the tide in those galleries rises or falls: at high water the roped crates float into a bridge; at low water the floor of the galleries is yours to walk.','The people I stopped counting are down there, and behind the stone they mortared over — the hammer will open it. Read their names, every one. The gate of my ledger-vault opens to nothing else.','“He calleth his own sheep by name, and leadeth them out.” — John 10:3'],
        toast:'🔔 The Tide Bell is yours — and his teaching is in your journal.',
        journal:'In the sea-caves under Saltmere\'s chapel I found {general}\'s tomb empty — his body hangs in the nave. The Lord gave me a vision of him: he sparred with me and asked me what a person is. {head}: {doc} He gave me his Tide Bell, and asked me to find the people he stopped counting — by name.',
        codex:['Genesis 1:27','So God created man in his own image, in the image of God created he him; male and female created he them.'] },
      folk:{name:'Sister Abigail',first:'The tide is ours again — we ring the bell twice a day, and the brothers read the names on the posts aloud, all of them, every time.',rest:'The General comes down at low water and walks the floor with us. He stops at every name. Every one.'},
      raiseWhy:['I was dead, knight. Truly dead. I counted my people until I could not see them — and the shadow took me in the middle of a sum, and hung me here with my ledger, to show the town what I had made of them.','And He has called me out of it, as He called Lazarus out of the tomb — by name. He did not count me. He called me. I am born again, and I will learn every name in Saltmere.'],
      goal:(c,inC,td)=>{ const nm=Object.keys(c.names||{}).length; return !c.seen?`${td.name}’s chapel is barred — go down the sea-stair in its churchyard.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep in the sea-caves.`:`Back down into ${td.name}’s sea-caves — ${td.general}’s tomb lies deepest.`)
        :nm<5?`Ring the Tide Bell in the flooded galleries, and find the uncounted — ${nm} of 5 names read.`:!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The ledger-vault is open — the great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the net-menders’ hall.':`Up the stair to the nave — ${td.boss} waits.`; } },
    3:{ entrance:'yew', wayIn:'in the churchyard an old yew has split open at its roots, and a stair goes down between them.', motif:'root',
      intro:['Damp earth and old leaves, and roots — roots everywhere, through the walls, through the tombs, thick as a man. The woodsmen of Thornwood are buried here.','The chapel overhead is bound by the dark. The way to it is down, among the roots.','Doors stay open once opened; halls stay cleared. Look for keys, and the map. And mind the dark below — it is darker than it ought to be.'],
      warden:{name:'The Rootbound Warden',tip:'👹 The Rootbound Warden — a brute grown through with roots: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'lantern',relic:'lantern',emoji:'🏮',name:'Deborah’s Lantern',take:'🙏 Take the lantern',zone:' · 🏮'},
      greatKey:['Heavy, gold, and warm to the touch. A lamp and a cross are cut into its bow.','It opens the great door at the head of the woodsmen’s hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The woodsmen keep a lamp burning in it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General walks the woods of Thornwood again — and carries her lamp indoors first.'],
        again:['Go up, knight, and take my lamp into the dark galleries. Burn the roots that choke the way. Find the heart of them.','It is not outside the walls. It never was. It is under the chapel, in the middle of the dark, and it has been there the whole time.','Burn it, and every root that grew from it will wither — the one sealing the vault too. Then the great key, the great door, and the nave — where my body hangs.'],
        open:['The tomb lies open, split through by roots — and it is empty. Only an old iron lantern lies in the leaf-litter where she was laid, unlit.','You kneel. And the dome fills with a light that no lamp gave.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the shadow came up out of the ground and took Thornwood. Within the month the roots split my tomb, and it was carried up into the nave and hung there in chains. But the dead are not lost to God. He lets you see me now, as He sees me.','I burned the rot out of Thornwood twice. Both times I looked outward — over the wall, into the woods, at the strangers on the road. I never once carried this lamp into my own house. The root was under my own chapel the whole time. It was under me.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You did not look past me for the danger. You watched the one in front of you.','So I will ask you what I could not answer — where the rot in a man comes from.'],
        give:['Then take my lantern — and my helm. I carried the lamp along the walls every night and never below. Carry it down, where it was always meant to go.','{tool} — it lights the dark galleries where no torch will burn, and Ⓐ Burn with it to set a root-tangle alight.','In the middle of the dark galleries, behind a knot of roots, is the heart they grow from. Burn it. Every root that grew from it will wither — the one over the vault in the woodsmen’s hall too.','“The spirit of man is the candle of the LORD, searching all the inward parts.” — Proverbs 20:27'],
        toast:'🏮 Deborah’s Lantern is yours — and her teaching is in your journal.',
        journal:'Down among the roots under Thornwood\'s chapel I found {general}\'s tomb empty — her body hangs in the nave. The Lord gave me a vision of her: she sparred with me and asked me where the rot in us comes from. {head}: {doc} She gave me her lantern, and told me the root was never outside the walls.',
        codex:['Romans 5:12','Wherefore, as by one man sin entered into the world, and death by sin; and so death passed upon all men, for that all have sinned.'] },
      folk:{name:'Brother Ash',first:'The roots died back the day the chapel was cleansed — all of them, all at once. We have been clearing them since. Good firewood, as it turns out.',rest:'The General comes down with her lamp every evening, before she walks the walls. Below first, she says. Always below first.'},
      raiseWhy:['I was dead, knight. Truly dead. I hunted the rot everywhere but in myself — and the shadow grew up through me while I watched the road, and hung me here, split through with its roots.','And He has called me out of it, as He called Lazarus out of the tomb. He searched me and knew me, and did not throw me away. I am born again, and I will carry the lamp inward first.'],
      goal:(c,inC,td)=>!c.seen?`${td.name}’s chapel is barred — go down between the roots of the old yew in its churchyard.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep among the roots.`:`Back down into ${td.name}’s root-crypts — ${td.general}’s tomb lies deepest.`)
        :!c.heart?'Carry the lantern into the dark galleries, burn the roots — and find their heart.':!c.bosskey&&!(c.doors&&c.doors['0:9,9'])?'The roots have withered — the vault in the woodsmen’s hall is open. The great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the woodsmen’s hall.':`Up the stair to the nave — ${td.boss} waits.` },
    4:{ entrance:'well', wayIn:'in the market square, by the Caravan Bazaar, the old town well has run dry — and a rope ladder hangs down its shaft into the cisterns below.', motif:'sun',
      intro:['Dry, warm air, and sand underfoot — sand drifted in down the well-shaft, years of it. The caravan-folk of Dusthaven are buried here, in the cisterns their fathers cut.','The chapel overhead is bound by the dark. The way to it is down, through the old cisterns.','Shafts of noon light come down through the rock, and bronze stands stand in the dark to carry it. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Gilded Warden',tip:'👹 The Gilded Warden — a brute plated in stolen gilt: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'mirror',relic:'mirror',emoji:'🪞',name:'Sun Mirror',take:'🙏 Take the mirror',zone:' · 🪞'},
      greatKey:['Heavy, gold, and warm to the touch. A sun and a cross are cut into its bow.','It opens the great door at the head of the cistern — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The caravan-folk have set a little bronze mirror in it, turned up to the oculus, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General preaches in Dusthaven again — and this time he preaches the whole of Him.'],
        again:['Go up, knight, to the Hall of the Teacher. They melted down the mirrors from every stand in the catacombs to gild those images — every one but mine.','There is an empty bracket in the hall where a mirror used to hang. Set mine in it, and turn the sun on the images. They are only plaster under the gilt.','When the last of them falls, the vault in the hall will open, and the great key with it. Then the great door in the cisterns — and the nave, where my body hangs.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a round mirror of polished bronze lies in the dust where he was laid, turned up to the light.','You kneel. And the dome fills with a light that is brighter than the noon.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the shadow came up the dry well and took Dusthaven. Within the month it carried me out of this tomb and up into the nave, and hung me there in chains. But the dead are not lost to God. He lets you see me now, as He sees me.','I preached a Christ my people could carry home: a good teacher, a brave man, a lamp for the road. Nothing they would need saving by. They loved it. They built Him a hall and filled it with His image — a kindly man with a lamp, and no wounds in His hands.','And a lamp, knight, cannot raise the dead. When the Ember Hollow came, the lamp I had given them was all they had, and it went out.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You did not take me for less than I am, and you did not take me for more.','So I will ask you what I could not answer — who He is.'],
        give:['Then take my mirror — and my cloak. I polished this glass every morning and never once looked into it. It does not shine by itself. Nothing does. It only gives back the light that falls on it.','{tool} — Ⓐ Set it in an empty mirror-bracket, and Ⓐ Turn it to send the sun where you will. The light it carries breaks the images the shadow gilded.','In the Hall of the Teacher above you there is an empty bracket where the brothers’ mirror hung. Set mine there. Turn the light on the images — every one. The vault behind them holds the great key.','“But we all, with open face beholding as in a glass the glory of the Lord, are changed into the same image from glory to glory.” — 2 Corinthians 3:18'],
        toast:'🪞 The Sun Mirror is yours — and his teaching is in your journal.',
        journal:'Down in the dry cisterns under Dusthaven\'s chapel I found {general}\'s tomb empty — his body hangs in the nave. The Lord gave me a vision of him: he sparred with me and asked me who Christ is. {head}: {doc} He gave me his Sun Mirror, and told me it only gives back the light that falls on it.',
        codex:['John 1:14','And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.'] },
      folk:{name:'Brother Elam',first:'The well filled again the day the chapel was cleansed — sweet water, the first in fifteen years. We have polished every mirror stand in the cisterns since.',rest:'The General comes down at noon, when the light is in the shafts, and stands in it a while. He says he finally knows what the mirror is for.'},
      raiseWhy:['I was dead, knight. Truly dead. I made the Lord small enough for my people to carry — a teacher, a lamp — and when the dark came, a lamp was not enough to save them, nor me.','And He has called me out of it, as He called Lazarus out of the tomb. No teacher does that. No good man does that. Only God made flesh. I am born again, and I will preach the whole of Him.'],
      goal:(c,inC,td)=>{ const ni=Object.keys(c.idols||{}).length; return !c.seen?`${td.name}’s chapel is barred — climb down the dry well in the market square.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the cisterns.`:`Back down the dry well — ${td.general}’s tomb lies deepest.`)
        :ni<10?`Set the Sun Mirror in the empty bracket in the Hall of the Teacher, and turn the light on the images — ${ni} of 10 fallen.`:!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The images are down — the vault in the Hall of the Teacher is open. The great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the cistern.':`Up the stair to the nave — ${td.boss} waits.`; } },
    5:{ entrance:'snowcrypt', wayIn:'by the cathedral wall a crypt door lies half-buried in a drift of snow — dig it clear, and its stair goes down into the crypts.', motif:'ice',
      intro:['Cold — a cold that goes straight to the bone, and the breath smoking in front of you. The pilgrims and brothers of Crystalpeak are buried here, under the mountain.','The cathedral overhead is bound by the dark. The way to it is down, through the crypts.','Ice on the floors, ice down the walls. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Frostbound Warden',tip:'👹 The Frostbound Warden — a brute rimed in ice: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'rope',relic:'rope',emoji:'🪢',name:'Lydia’s Rope',take:'🙏 Take the rope',zone:' · 🪢'},
      greatKey:['Heavy, gold, and warm to the touch — the only warm thing in the crypts. A coil of rope and a cross are cut into its bow.','It opens the great door at the head of the frost hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The brothers have hung a rope over it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General walks Crystalpeak again — and sleeps through the night.'],
        again:['Go up, knight, to the frozen falls. The high ledge — I climbed at it every night of my life and never once reached it.','There is a pulley over it. Cast my rope over the pulley and let it take you up. Do not climb. You cannot climb it. Let it lift you.','The great chest is on the ledge. Then the great door in the frost hall — and the nave, where my body hangs.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a coil of rope lies where she was laid, and no frost has touched it.','You kneel. And the dome fills with a light that is warm.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the cold came down the mountain and took Crystalpeak. Within the month it carried me out of this tomb and up into the nave, and hung me there in chains. But the dead are not lost to God. He lets you see me now, as He sees me.','I was pardoned, knight. Years before. The debt was torn up in front of me. And I could not believe it — so I set out to deserve it. Every night I went down to the falls and climbed, to pay a little more of what was already paid.','The Frost Revenant never struck me once. It did not need to. It only let me work, out in the cold, until I had earned everything — and could no longer feel my hands.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. And you did not try to win it all at once. You waited, and took the moment when it was given.','So I will ask you what I could not answer — what it means to be declared righteous.'],
        give:['Then take my rope — and my ring. The brothers gave me the rope the year I was pardoned. I never once let it take my weight.','{tool} — at the foot of a ledge too high and too slick to climb, Ⓐ cast it over the iron pulley above. It will lift you. Not your strength. That is the whole of it.','At the frozen falls above you there is a pulley over the high ledge. The great chest is up there. Let the rope take you up to it.','“He brought me up also out of an horrible pit, out of the miry clay, and set my feet upon a rock.” — Psalm 40:2'],
        toast:'🪢 Lydia’s Rope is yours — and her teaching is in your journal.',
        journal:'Down in the crypts under Crystalpeak\'s cathedral I found {general}\'s tomb empty — her body hangs in the nave. The Lord gave me a vision of her: she sparred with me and asked me what it means to be justified. {head}: {doc} She gave me her rope, and told me not to climb it — to let it lift me.',
        codex:['Ephesians 2:8–9','For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast.'] },
      folk:{name:'Brother Simeon',first:'The ice let go the day the cathedral was cleansed. The falls are running again — you can hear them from the nave. We have a fire in every crypt now.',rest:'The General comes down to the falls sometimes. She does not climb them any more. She sits by the water and listens. She says she is learning to rest.'},
      raiseWhy:['I was dead, knight. Truly dead. I was forgiven and I would not take it — I worked to earn what was already given, until the cold had all of me, and the shadow hung me here to show the town what my striving was worth.','And He has called me out of it, as He called Lazarus out of the tomb. Lazarus did not help. Neither could I. I am born again — by grace, and not of works — and I am learning to rest in it.'],
      goal:(c,inC,td)=>!c.seen?`${td.name}’s cathedral is barred — dig clear the snow-buried crypt door by its wall.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the crypts.`:`Back down into ${td.name}’s crypts — ${td.general}’s tomb lies deepest.`)
        :!c.bosskey&&!(c.doors&&c.doors['0:9,9'])?'At the frozen falls, cast Lydia’s rope over the pulley — the great chest waits on the high ledge.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the frost hall.':`Up the stair to the nave — ${td.boss} waits.` },
    6:{ entrance:'ashcellar', wayIn:'in the churchyard a cellar door lies half-sunk in a drift of ash — clear it, and its stair goes down into the cellars.', motif:'ash',
      intro:['Heat — still, after fifteen years — and the bitter smell of old burning. The folk of Ashfield are buried here, under the town that burned.','The chapel overhead is bound by the dark. The way to it is down, through the cellars.','Ash in drifts, and fire still breathing in the floors. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Charred Warden',tip:'👹 The Charred Warden — a brute still smouldering: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'horn',relic:'horn',emoji:'📯',name:'Gideon’s Horn',take:'🙏 Take the horn',zone:' · 📯'},
      greatKey:['Heavy, gold, and cool to the touch — the only cool thing in the cellars. A ram’s horn and a cross are cut into its bow.','It opens the great door at the head of the cellar hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The brothers have set a sprig of green in it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General keeps Ashfield again — and listens before he speaks.'],
        again:['Go up, knight, to the burnt galleries. The brothers’ wind-vanes there have not turned since the fire.','Blow my horn at them — not as I blew it. Not to call the town to me. Blow it, and let the breath go where it will.','Blow away the ash that chokes the last of them. When all three turn the smoke will go, and the vault with the great key will open. Then the great door in the cellars — and the nave, where my body hangs.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a ram’s horn lies in the ash where he was laid, and no ash has settled on it.','You kneel. And the dome fills with a light, and a stir of air like a breath.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I fell fifteen years ago, when the fire took Ashfield. Within the month the shadow carried me out of this tomb and up into the nave, and hung me there in chains. But the dead are not lost to God. He lets you see me now, as He sees me.','I wanted the fire of Pentecost. I was loud, and tireless, and certain — and I called all of it the Spirit, because it felt like power. The Char Demon gave me every bit of the fire I asked for. Ashfield burned for eleven days.','The Spirit is not my zeal turned up hot. He is the breath of God, and He blows where He wills — and He gives life to the dead. I never once waited for Him. I only ever shouted.','Before you go up, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You did not rush me. You waited for the moment, and took it when it came.','So I will ask you what I could not answer — how the dead are made alive.'],
        give:['Then take my horn — and my sword. I blew this horn to call the town to me. Blow it now and let the breath go where it is sent.','{tool} — Ⓐ Blow it at the ash that chokes a way and the breath will scatter it; blow it at the brothers’ wind-vanes and they will turn.','In the burnt galleries above you, three vanes stand still. Turn them all — the smoke will go, and the vault with the great key will open.','“Come from the four winds, O breath, and breathe upon these slain, that they may live.” — Ezekiel 37:9'],
        toast:'📯 Gideon’s Horn is yours — and his teaching is in your journal.',
        journal:'Down in the ash-choked cellars under Ashfield\'s chapel I found {general}\'s tomb empty — his body hangs in the nave. The Lord gave me a vision of him: he sparred with me and asked me how the dead are made alive. {head}: {doc} He gave me his ram\'s horn, and told me to let the breath go where it is sent.',
        codex:['John 3:8','The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.'] },
      folk:{name:'Brother Hadad',first:'The fires in the floors went out the day the chapel was cleansed — all of them at once, like a breath blown out. We have swept the cellars since. There is green coming up in the churchyard.',rest:'The General comes down to the galleries sometimes and stands under the vanes and watches them turn. He does not say anything. He says he is learning to listen.'},
      raiseWhy:['I was dead, knight. Truly dead. I took my own fire for the Spirit of God, and it burned my town and me with it, and the shadow hung me here in the smoke.','And He has called me out of it, as He called Lazarus out of the tomb — not with shouting, but with a word. I am born again, of water and of the Spirit, and this time I will wait to hear Him.'],
      goal:(c,inC,td)=>{ const nv=Object.keys(c.vanes||{}).length; return !c.seen?`${td.name}’s chapel is barred — clear the ash from the cellar door in its churchyard.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the cellars.`:`Back down into ${td.name}’s cellars — ${td.general}’s tomb lies deepest.`)
        :nv<3?`Blow Gideon’s horn at the wind-vanes in the burnt galleries — ${nv} of 3 turning.`:!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The vanes are turning — the vault in the burnt galleries is open. The great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the cellar hall.':`Up the stair to the nave — ${td.boss} waits.`; } },
    7:{ entrance:'royalcrypt', wayIn:'beside King Karl’s keep a stair goes down into the royal crypt — a guard keeps its gate, and he does not like what he hears down there at night.', motif:'storm',
      intro:['Damp stone and the smell of rain, and a hum in the air like a storm about to break. The kings of Stormgate are buried here, and their guard, and their people.','The cathedral overhead is bound by the dark. The way to it is down, through the royal crypt.','Lightning still crawls in the old storm-columns. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Stormbound Warden',tip:'👹 The Stormbound Warden — a brute crackling with storm-light: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'shield',relic:'shield',emoji:'🛡️',name:'Ruth’s Shield',take:'🙏 Take the shield',zone:' · 🛡️'},
      greatKey:['Heavy, gold, and humming faintly in your hand. A shield and a cross are cut into its bow.','It opens the great door at the head of the crypt hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The guard have hung a shield over it, the way they mark a grave they are glad of.','“He is not here: for he is risen.” — Matthew 28:6 · The General keeps the king’s door again — and knows the name of everyone who passes it.'],
        again:['Go up, knight, to the storm galleries. Stand in the lightning with my shield raised — hold your guard, and it will not touch you.','And turn the shield to the copper rods, and the bolt will go where you send it. Three rods, and the vault with the great key opens. There is a little room behind the lightning, too, for anyone with a shield.','Then the great door in the crypt — and the nave. The king is there, knight. It is in him. Do not strike him. Turn his blows, and the storm will come out of him.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a round shield lies where she was laid, and the damp has not touched it.','You kneel. And the dome fills with a light like the sky after a storm.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I was captain of the king’s guard. I kept King Karl’s door ten years, and I never once asked after his soul. I counted the stones of Stormgate and not its sheep. I mended the gates while no one preached the Word in his hall.','The thing I guarded him from was already inside him. When the dark came, it was the king’s own hand, crackling with storm-light, that struck me down at his side. Within the month the shadow carried me out of this tomb and hung me in the nave. But the dead are not lost to God. He lets you see me now, as He sees me.','The king is up there, knight. The Thunder Lord is in him. Before you go, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. You held your guard over yourself. Now learn to hold it over someone else.','So I will ask you what I could not answer — what the church is.'],
        give:['Then take my shield. I carried it ten years at a door, and never once held it over anyone. Hold it over them.','{tool} — raise it (hold Guard) and the lightning breaks on it and does not touch you; turn it to a copper rod and the bolt goes where you send it.','In the storm galleries above, three rods want the lightning. Send it to all three and the vault with the great key will open. And in the nave — the king. Do not strike him. Turn his blows with this, and the storm will come out of him.','“Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked.” — Ephesians 6:16'],
        toast:'🛡️ Ruth’s Shield is yours — and her teaching is in your journal.',
        journal:'Down in the royal crypt under Stormgate I found {general}\'s tomb empty — her body hangs in the nave. The Lord gave me a vision of her: she sparred with me and asked me what the church is. {head}: {doc} She gave me her shield, and told me the king is in the nave with the storm inside him — and not to strike him.',
        codex:['1 Peter 2:5','Ye also, as lively stones, are built up a spiritual house, an holy priesthood, to offer up spiritual sacrifices, acceptable to God by Jesus Christ.'] },
      folk:{name:'Sergeant Abner',first:'The storm-columns went quiet the day the cathedral was cleansed. The king came down here himself the next morning — to the tombs of his fathers, and then to hers. He stood a long time.',rest:'The General walks the crypt with the king now, of an evening. They do not count the stones. They talk about the people.'},
      raiseWhy:['I was dead, knight. Truly dead. I kept the walls and lost the people, and the storm I guarded the king from struck me down with his own hand, and the shadow hung me here.','And He has called me out of it, as He called Lazarus out of the tomb — by name, as a shepherd calls his own. I am born again, a living stone, and I will keep the people this time, and not the stones.'],
      goal:(c,inC,td)=>{ const nr=Object.keys(c.rods||{}).length; return !c.seen?`${td.name}’s cathedral is barred — go down into the royal crypt beside King Karl’s keep.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the royal crypt.`:`Back down into the royal crypt — ${td.general}’s tomb lies deepest.`)
        :nr<3?`Raise Ruth’s shield in the lightning of the storm galleries and send it to the copper rods — ${nr} of 3 charged.`:!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The rods are charged — the vault in the storm galleries is open. The great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the crypt hall.':`Up the stair to the nave — the king is there. Turn his blows; do not strike him.`; } },
    8:{ entrance:'barrow', wayIn:'out past the last houses of Shadowmere a barrow of the old knights stands in the marsh grass, its stone door sealed. They say it opens to a bell.', motif:'shadow',
      intro:['Cold stone, black and polished, and somewhere water dripping. The knights of Shadowmere are buried here — rank on rank of them, laid out in their armour.','The chapel overhead is bound by the dark. The way to it is down, through the barrow.','Everything you have been given will be wanted here, knight. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Drowned Warden',tip:'👹 The Drowned Warden — a brute, black water running off it: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'oil',relic:'oilhorn',emoji:'🫒',name:'Samuel’s Horn of Oil',take:'🙏 Take the horn of oil',zone:' · 🫒',verb:'Anoint',seal:'The knights’ seal',sealLook:['A seal cut into the gate: a sword, and a crown over it. The stone round it is dark, as if it had been oiled once and the oil gone into it.','It does not want a key. It wants anointing.']},
      greatKey:['Heavy, gold, and cold as the barrow. A horn and a cross are cut into its bow.','It opens the great door at the head of the barrow hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The knights’ widows have left a little flask of oil on it, the way you anoint a thing that is set apart.','“He is not here: for he is risen.” — Matthew 28:6 · The General rides the marsh road again — and does not look at the dark too long.'],
        again:['Go up, knight, to the galleries. Anoint the knights’ seal on the vault with the oil — it opens to nothing else — and the great key is yours.','Then the great door in the barrow hall, and the nave.','The thing up there will wear your shape. Do not admire it. Do not look at it any longer than it takes to strike it.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a horn, capped in gold, lies where he was laid. It smells of olive oil.','You kneel. And the dome fills with a light that throws no shadow at all.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I was captain of the knights of Shadowmere. I studied the enemy longer than any man living. I knew their ranks and their names. I came to admire the discipline of some of them — and admiring is only a short step from wanting.','When the Dark Paladin came, it came in the shape I admired, and I lowered my sword to look closer. That was all it needed. But the dead are not lost to God. He lets you see me now, as He sees me.','Before you go up to it, let me see you stand. Guard as my blow lands — not before, not after — and you will turn it whole. Turn two of them, or drive me back.'],
        sparWin:['…Good. You watched my blade, not my face. That is the whole of it.','So I will ask you what I knew too well, and believed too little.'],
        give:['Then take this — the horn of oil. Samuel of old filled his horn and went out to anoint a king, and did not look on the outward appearance.','{tool} — the knights’ seal on the vault in the galleries wants anointing. Nothing else will open it. The great key is inside.','And in the nave: it will copy you. Strike the one that is not a reflection. The angels that kept the faith are on your side of the fight, knight, not the other — and there are more of them.','“For the LORD seeth not as man seeth; for man looketh on the outward appearance, but the LORD looketh on the heart.” — 1 Samuel 16:7'],
        toast:'🫒 Samuel’s Horn of Oil is yours — and his teaching is in your journal.',
        journal:'Down in the barrow under Shadowmere I found {general}\'s tomb empty — his body hangs in the nave. The Lord gave me a vision of him: he sparred with me and asked me what Scripture teaches about demons. {head}: {doc} He gave me his horn of oil to anoint the knights\' seal on the vault, and told me the thing in the nave will wear my shape.',
        codex:['Hebrews 1:14','Are they not all ministering spirits, sent forth to minister for them who shall be heirs of salvation?'] },
      folk:{name:'Brother Ansel',first:'The water went down the day the chapel was cleansed — all on its own, with no bell. We found the knights’ helms lying in rows on the floor of the galleries, washed clean.',rest:'The General comes down of an evening and reads their names. He does not read the enemy’s any more. He says he has forgotten most of them, and is glad.'},
      raiseWhy:['I was dead, knight. Truly dead. I looked at the dark until I stopped seeing it as dark, and it took the shape I admired, and I lowered my sword.','And He has called me out of it, as He called Lazarus out of the tomb — by name, as a shepherd calls his own. I will keep my eyes on Him now, and know the enemy only as well as I need to beat him.'],
      goal:(c,inC,td)=>!c.dug&&!c.seen?`${td.name}’s chapel is barred — ring the Tide Bell at the knights’ barrow out in the marsh, past the last houses.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the barrow — every tool you carry will be wanted.`:`Back down into ${td.name}’s barrow — ${td.general}’s tomb lies deepest.`)
        :!(c.gates&&c.gates['1:4'])?'Anoint the knights’ seal on the vault in the drowned galleries with Samuel’s horn of oil.':!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The vault in the drowned galleries is open — the great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the barrow hall.':`Up the stair to the nave — ${td.boss} waits. It will wear your shape.` },
    9:{ entrance:'ossuary', wayIn:'by the cathedral wall stands the pilgrims’ ossuary, its door sealed with a stone and an iron ring. A crook could drag it clear.', motif:'void',
      intro:['Dry bone and old smoke, and a quiet so deep it hums. The pilgrims who died at Hellgate’s gate are laid here, shelf over shelf — ten thousand of them.','The cathedral overhead is bound by the dark. The way to it is down, through the ossuary.','Everything you have been given will be wanted here, knight. Doors stay open once opened; halls stay cleared. Look for keys, and the map.'],
      warden:{name:'The Void Warden',tip:'👹 The Void Warden — a brute with the dark showing through it: its blows come after a long heave. Roll clear, or parry, and strike while it reels.'},
      tool:{flag:'trumpet',relic:'trumpet',emoji:'🎺',name:'Michael’s Trumpet',take:'🙏 Take the trumpet',zone:' · 🎺',verb:'Sound',seal:'The sealed vault',sealLook:['A gate of black iron with a gold mouth set in it, like the bell of a horn turned to the wall.','No key fits it. The brothers’ mark over it: a trumpet, and a cross, and the words “at the last”.']},
      greatKey:['Heavy, gold, and warm — the only warm thing down here. A trumpet and a cross are cut into its bow.','It opens the great door at the head of the ossuary hall — and the stair to the nave, where the guardian waits.'],
      tomb:{ clean:['Still empty — and now it always will be. The pilgrims’ children have laid palm branches over it.','“He is not here: for he is risen.” — Matthew 28:6 · The General keeps the gate again — and sleeps at night.'],
        again:['Go up, knight, to the void galleries. Sound the trumpet at the sealed vault — one note — and the great key is yours.','Then the great door in the ossuary hall, and the nave.','The thing up there will offer you rest. Do not take rest from it. Take it from Him — and keep striking.'],
        open:['The tomb lies open, the lid pushed aside — and it is empty. Only a long trumpet of old gold lies where he was laid, and the dust has not settled on it.','You kneel. And the dome fills with a light like morning.'],
        vision:['Do not be afraid. I am not a ghost, knight — I am dead, and my body is not here.','I kept Hellgate’s gate twenty years. I fought as if the last day hung on the strength of my arm — as if the ending were mine to hold up. I had no rest in me, and no joy.','When the Void Champion came, it offered to take the weight. It showed me an ending with nothing on the other side of it — and for one moment I was grateful, and I laid down. But the dead are not lost to God. He lets you see me now, as He sees me.','Let me see you stand before you go up. Guard as my blow lands — not before, not after. Turn two of them, or drive me back.'],
        sparWin:['…Well stood. And you are not holding the world up while you do it. Good.','Then I will ask you the last thing — the thing I forgot.'],
        give:['Then take my trumpet. I never once blew it. I thought it was for the end, and the end was mine to keep away.','{tool} — sound it at the sealed vault in the galleries and the vault will open. The great key is inside.','In the nave the Champion drains your hope while you hold back, and gives it back while you strike. Strike. The voids will offer you rest — they mend it, not you. The ending is not yours to hold up, knight. It is His to bring.','“For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first.” — 1 Thessalonians 4:16'],
        toast:'🎺 Michael’s Trumpet is yours — and his teaching is in your journal.',
        journal:'Down in the ossuary under Hellgate I found {general}\'s tomb empty — his body hangs in the nave. The Lord gave me a vision of him: he sparred with me and asked me about the Christian hope of resurrection. {head}: {doc} He gave me his trumpet to sound at the sealed vault, and told me the ending is not mine to hold up.',
        codex:['1 Corinthians 15:52','In a moment, in the twinkling of an eye, at the last trump: for the trumpet shall sound, and the dead shall be raised incorruptible, and we shall be changed.'] },
      folk:{name:'Brother Jude',first:'We came back down the day the cathedral was cleansed. The lightning in the galleries had gone out, and the hum with it. It is only quiet now — the good kind.',rest:'Ten thousand names, and we read them all, a hundred a night. The General comes and reads with us. He has a good voice for it.'},
      raiseWhy:['I was dead, knight. Truly dead. I held the ending up so long that when the dark offered to take it from me, I let it — and lay down in the void.','And He has called me out of it, as He called Lazarus out of the tomb — by name. He was always going to bring the ending. I only have to keep the gate till He does.'],
      goal:(c,inC,td)=>!c.dug&&!c.seen?`${td.name}’s cathedral is barred — drag the seal-stone from the pilgrims’ ossuary by its wall with the Shepherd’s Staff.`:!c.trial?(inC?`Find ${td.general}’s tomb, deep under the ossuary — every tool you carry will be wanted.`:`Back down into ${td.name}’s ossuary — ${td.general}’s tomb lies deepest.`)
        :!(c.gates&&c.gates['1:4'])?'Sound Michael’s trumpet at the sealed vault in the void galleries.':!(c.doors&&c.doors['0:9,9'])&&!c.bosskey?'The vault in the void galleries is open — the great key is inside.':!(c.doors&&c.doors['0:9,9'])?'The great door at the head of the ossuary hall.':`Up the stair to the nave — ${td.boss} waits. Keep striking.` } };


  const SOLID=new Set(['#','T','O','C','Q','l','t','k','R','X','v','B','A','Y','N','F','E','Z','J','w','W','I','n','r','j','U','M','e','i','o','a','y','f','x']);
