  let _glowM=null, _poolM=null;
  function radial(c0){ const c=document.createElement('canvas'); c.width=c.height=64; const g=c.getContext('2d'), gr=g.createRadialGradient(32,32,0,32,32,32); gr.addColorStop(0,c0); gr.addColorStop(1,'rgba(255,170,80,0)'); g.fillStyle=gr; g.fillRect(0,0,64,64); return new THREE.CanvasTexture(c); }
  const EMBERS={}; function emberM(k){ return EMBERS[k]||(EMBERS[k]=new THREE.MeshBasicMaterial({color:0xff6a20,transparent:true,opacity:0.5,depthWrite:false,blending:THREE.AdditiveBlending})); }
  let _iceM=null; function iceM(){ return _iceM||(_iceM=new THREE.MeshPhongMaterial({color:0xbfe4f4,transparent:true,opacity:0.72,shininess:140,specular:0xffffff,depthWrite:false})); }
  function glowMat(){ return _glowM||(_glowM=new THREE.SpriteMaterial({map:radial('rgba(255,190,110,0.9)'),transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,opacity:0.5})); }
