    const inR=(r,x,y)=>x>=r[0]&&x<=r[2]&&y>=r[1]&&y<=r[3], DM=D.dome, inDome=(x,y)=>!!DM&&Math.hypot(x-DM.c[0],y-DM.c[1])<=DM.r+0.6;
