    const WH=(x,y)=>{ let h=CW; for(let dy=-1;dy<=1;dy++) for(let dx=-1;dx<=1;dx++){ const c=rows[y+dy]&&rows[y+dy][x+dx]; if(c!==undefined&&c!=='#') h=Math.max(h,HC(x+dx,y+dy)+(inDome(x+dx,y+dy)?DM.r*0.55:0)); } return h; };
    const pal={wall:dk(T.wall,0.72),top:dk(T.top,0.6),fA:dk(T.fA,0.86),fB:dk(T.fB,0.86),trim:T.trim,stone:0x8a8070,lid:0x9a9080,iron:0x2a2a30,wood:0x5a3a22,linen:0xd8ccb0};
    const scene=new THREE.Scene(), bg=new THREE.Color(0x0a0709); scene.background=bg; scene.fog=new THREE.Fog(bg,5,21);
    const lv={id,name:td.name+' Catacombs',scene,folk:[],spots:[],anim:[],cam:{pitch:0.22,dist:2.9,min:1.5,max:4.6,lookH:0.15},speed:4.4,interior:true,actorS:0.78,dmapShow:true};
    const MF=(CFG[t]||CFG[0]).motif, hemi=new THREE.HemisphereLight(MF==='net'?0xb8d8e0:MF==='root'?0xc8d8a8:MF==='sun'?0xf4dcb0:MF==='ice'?0xd0e4f8:MF==='ash'?0xe0c0a0:MF==='storm'?0xc8d4e8:0xe8d0b8,MF==='net'?0x14262a:MF==='root'?0x1a2212:MF==='sun'?0x2e2214:MF==='ice'?0x182434:MF==='ash'?0x2a140c:MF==='storm'?0x141a26:0x2a1e1a,MF==='ice'?0.62:0.5); scene.add(hemi); const lamp=new THREE.PointLight(0xffd8a0,0.9,8,1.5); scene.add(lamp);
    const room=group(0,0,0,scene), an=lv.anim, dyn={doors:{},chests:{},lamps:[],blocks:[],plates:[],levers:{},crack:null};
    const wallC=(x,y)=>at(x,y)==='#'||at(x,y)===undefined, floorC=(x,y)=>{ const c=at(x,y); return c!==undefined&&c!=='#'&&c!=='X'; };
    const WI=wallInset((x,y)=>wallC(x,y),(x,y)=>floorC(x,y)||at(x,y)==='X',0.06);
