    let tideY=0; const tideWant=()=>WZ&&!clean()&&tideSt()==='hi'?WZ.hi:0, deep=()=>tideY>0.45;
    const hG=(x,y)=>inWater(x,y)&&at(x,y)==='D'?tideY+0.25:hAt(x,y);   /* the ground you stand on: a crate rides the water */
